select prdposition.ENDDATE RAISING_DATE,/*募集日期（月末日期）*/ prdbaseinfo.PROD_ID PROD_ID,/*中债产品代码*/ prdbaseinfo.PBC_PROD_ID PBC_PROD_ID,/*人行产品代码*/ prdposition.BUY_PLACE BUY_PLACE,/*地区代码*/ prdposition.CUSTOMER_TYPE2 CUSTOMER_TYPE1,/*客户一级类型*/ prdposition.ccy ccy,/*币种*/ nvl(prdposition.DIRTYAMTSUM,0) RAISING_AMTSUM,/*当期申购金额=当期募集金额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ nvl(prdposition.DIRTYQTY,0) RAISING_QTY,/*当期申购份额=当期募集份额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ /*非净值型产品赎回交易取值（01 赎回金额=金额，赎回份额=份额；02 赎回金额=份额，赎回份额=份额；03 赎回金额=金额，赎回份额=金额)*/ case when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '01' then nvl(PRDPOSITION.REDAMT,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '02' then nvl(PRDPOSITION.REDQTY,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '03' then nvl(PRDPOSITION.REDAMT,0) else nvl(prdposition.REDAMT,0) end as REDAMT,/*当期兑付/赎回金额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ case when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '01' then nvl(PRDPOSITION.REDQTY,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '02' then nvl(PRDPOSITION.REDQTY,0) when prdbaseinfo.OPERATE_MODE in (3,5) and #{pbcProdRaising,jdbcType=VARCHAR} = '03' then nvl(PRDPOSITION.REDAMT,0) else nvl(prdposition.REDQTY,0) end as REDQTY,/*当期兑付/赎回份额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ nvl(prdposition.ENDAMTSUM_OTH,0) ENDAMTSUM,/*期末产品金额，需另外按照产品代码、地区代码、客户类型、币种代码汇总*/ nvl(prdposition.ENDQTYSUM,0) ENDQTY,/*期末产品份额，需另外按照产品代码、地区代码、客户类型、币种代码汇*/ decode(prdbaseinfo.OPERATE_MODE,'2',nvl(maxyield.PROD_VALUE,1),'4',nvl(maxyield.PROD_VALUE,1),null) PROD_VALUE,/*净值型产品期末净值*/ decode(prdbaseinfo.OPERATE_MODE,'2',nvl(maxyield.UNIT_VALUE_TOTAL,1),'4',nvl(maxyield.UNIT_VALUE_TOTAL,1),null) UNIT_VALUE_TOTAL,/*净值型产品期末累计净值*/ decode(prdbaseinfo.OPERATE_MODE,'3',prdbaseinfo.HIGH_YIELD_ISSUE,null) PROD_HIGH_YIELD,/*开放式非净值型产品预期最高收益率*/ decode(prdbaseinfo.OPERATE_MODE,'3',prdbaseinfo.LOW_YIELD_ISSUE,null) PROD_LOW_YIELD,/*开放式非净值型产品预期最低收益率*/ maxyield.CCY YEILD_CCY,/*收益率币种*/ prdposition.ORG_CODE ORG_CODE FROM PBC_MONTH_PRD_POSITION PRDPOSITION inner JOIN ( SELECT PROD_ID, PBC_PROD_ID, OPERATE_MODE, HIGH_YIELD_ISSUE, LOW_YIELD_ISSUE, RANK() OVER (PARTITION BY PROD_ID ORDER BY NVL(UPDATE_TIME,CREATE_TIME) DESC) RANKNUM from PBC_PRD_BASEINFO_SUB where PBC_PROD_ID is not null ) prdbaseinfo ON PRDPOSITION.PRODID = PRDBASEINFO.PROD_ID AND RANKNUM = 1 left join ( /*取离月末最近的净值和收益率，不需要判断CHANG_TYPE，默认净值型产品存净值，预期收益率产品存收益率*/ select YIELD.PROD_VALUE, YIELD.PROD_ID, YIELD.UNIT_VALUE_TOTAL, YIELD.CCY, rank() over (partition by yield.PROD_ID,yield.ccy order by YIELD.CHANGE_DATE desc) ranknum/*按产品+币种维度分类，按变动日期降序排序取最大的日期的净值*/ FROM CHB_PRD_PERIODYIELD YIELD WHERE 1 =1 AND YIELD.STATUS != 'D' AND to_char(YIELD.CHANGE_DATE,'yyyy-MM-dd') <= #{cdate,jdbcType=VARCHAR} ) maxyield on PRDPOSITION.PRODID = maxyield.PROD_ID and maxyield.ranknum = 1 where 1 =1 and to_char(prdposition.ENDDATE,'yyyy-MM-dd') = #{cdate,jdbcType=VARCHAR}
and (prdposition.BUY_PLACE not in('210200','330200','350200','370200','440300') or prdposition.BUY_PLACE is null)
#{prodid,jdbcType=VARCHAR}

select a.REGIST_SEQNO, a.RAISING_DATE, nvl(t2.pbc_code,a.PBC_PROD_ID)PBC_PROD_ID, a.BUY_PLACE, a.CUSTOMER_TYPE1, a.CCY, a.RAISING_AMTSUM, a.RAISING_AMTSUM_CNY, a.RAISING_QTY, a.REDAMT, a.REDAMT_CNY, a.REDQTY, a.ENDAMTSUM, a.ENDAMTSUM_CNY, a.ENDQTY, a.PROD_VALUE, a.PROD_VALUE_CNY, a.UNIT_VALUE_TOTAL, a.UNIT_VALUE_TOTAL_CNY, a.PROD_HIGH_YIELD, a.PROD_LOW_YIELD from PBC_PROD_RAISING_SUB a left join PBC_PRD_BASEINFO_SUB b on a.PBC_PROD_ID = b.PBC_PROD_ID LEFT JOIN( SELECT inside_prod_id, pbc_code FROM pbc_prod_assetpool_code WHERE status='E' AND code_type='01' )t2 ON t2.inside_prod_id=b.PROD_ID
